    "C36","C58","C62",
    "C63","C64","C65","C66","C67","C68","C70","C71","C72","C74"
  ],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": [
    "C03","C04","C05","C06","C09","C11","C15","C17",
    "C36","C58","C62",
    "C63","C64","C65","C66","C67","C68","C70","C71","C72","C74"
  ],
  "claims": [
    {
      "claim": "All transferable L1 gold records report measured oral bioavailability values ≥29% (sildenafil 41%, trovafloxacin 87.6%, ofloxacin ~100%, emtricitabine 92%, didanosine 29±6%, zalcitabine 80% in humans), with no L1 record supporting F <20%.",
      "card_ids": ["C03","C04","C05","C06","C09","C11","C15","C17"]
    },
    {
      "claim": "The closest L3 analog (M03, LCB01-0371) shares the 3-fluoro-4-(5-(hydroxymethyl)-2-oxooxazolidin-3-yl)phenyl substructure with the query and shows substantial oral exposure (AUC0-last 18,636 ng·h/mL after 800 mg PO), supporting adequate absorption.",
      "card_ids": ["C36"]
    },
    {
      "claim": "L5 gut-wall efflux/intestinal metabolism records for the oxazolidinone rivaroxaban show high Caco-2 permeability with only weak efflux, indicating the N-aryl oxazolidinone scaffold is not associated with efflux-limited absorption.",
      "card_ids": ["C58","C62"]
    },
    {
      "claim": "L6 hepatic clearance records for the closest tetrazole/pyridine oxazolidinone analog (M01, DA-7867) show negligible hepatic first-pass in rats (IV vs intraportal AUC not significantly different; no change with CYP inhibitor SKF 525-A) and only ~21.8% intestinal first-pass, indicating no hepatic clearance-driven presystemic loss.",
      "card_ids": ["C65","C68","C70","C71"]
    },
    {
      "claim": "Additional L6 human liver microsome records for oxazolidinone analogs show low-to-modest predicted hepatic/intrinsic clearance (e.g., 5.7–8.4 mL/min/kg predicted hepatic clearance; rivaroxaban HLM Clint 4.0 µL/min/mg), consistent with limited hepatic metabolic clearance.",
      "card_ids": ["C63","C64","C66","C67","C72","C74"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C63","C64","C65","C66","C67","C68","C69","C70","C71","C72","C73","C74"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "No matched oral versus intravenous exposure data for the query; C36 reports AUC only without an IV comparator.",
    "No query-specific hepatic clearance or metabolic-stability measurement; L6 records are for analogs, with the closest analog differing at the C5 oxazolidinone substituent and using rat/in vitro systems.",
    "No query-specific intestinal absorption, permeability, or gut-wall efflux measurement; L4/L5 records are for other molecules.",
    "No formulation-, food-effect-, or disease-state-specific data for the query.",
    "Transferable gold contexts are not structurally matched to the query; their F values are directional context, not direct evidence."
  ],
  "decision_summary": "Prediction remains high and is strengthened: L6 hepatic clearance/metabolic stability records for the closest oxazolidinone analog (DA-7867) show negligible hepatic first-pass and no significant CYP-mediated clearance, and additional HLM records show low-to-modest hepatic clearance; combined with prior gold F≥29% contexts, substantial oral AUC for the closest hydroxymethyl-oxazolidinone analog, and high permeability/weak efflux for rivaroxaban, there is no affirmative evidence for F<20%."
}

